from pathlib import Path
from datetime import datetime, timezone
ROOT=Path('/Users/pcoffeep/AgentPlayground/active-projects/mVllm_2')
SOURCES=ROOT/'docs/results/evaluation-tokenizer-compatibility-materials-20261016/tokenizer-sources.json'
DEFAULT_OUT=ROOT/'docs/results/evaluation-review-environment-audit-20261016.json'
sys.path.insert(0,str(ROOT))
from finetune.eval_review import MODEL_DIGESTS, REVIEW_RUNTIME
from finetune import eval_review_deployment as dep
from finetune import eval_audit_isolation
sha=lambda b:hashlib.sha256(b).hexdigest()
def file_sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
def read_url(path, body=None):
 import urllib.request
 class NoRedirect(urllib.request.HTTPRedirectHandler):
  def redirect_request(self,*a,**k): raise ValueError('redirect rejected')
 opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect())
 req=urllib.request.Request(REVIEW_RUNTIME['endpoint']+path,data=body,headers={'Content-Type':'application/json'},method='POST' if body else 'GET')
 with opener.open(req,timeout=4) as r:return json.loads(r.read())
def ps():
 try:
  x=read_url('/api/ps')
  return {'reachable':True,'models':[{'name':i.get('name'),'digest':i.get('digest'),'size':i.get('size'),'size_vram':i.get('size_vram')} for i in x.get('models',[])]}
 except Exception as e:return {'reachable':False,'error_type':type(e).__name__,'error':str(e)[:300]}
def snapshot_sources_and_providers():
 raw=SOURCES.read_bytes(); value=json.loads(raw); inventory={str(SOURCES):sha(raw)}
 provider_paths=[Path(dep.__file__).resolve(),Path(sys.modules['finetune.eval_review'].__file__).resolve(),Path(eval_audit_isolation.__file__).resolve()]
 for p in provider_paths: inventory[str(p)]=file_sha(p)
 for spec in value.values():
  for n in spec['files']: inventory[str(Path(spec['path'])/n)]=file_sha(Path(spec['path'])/n)
  aud=Path(spec['tokenizer_equivalence_audit']['path']); inventory[str(aud)]=file_sha(aud)
  a=json.loads(aud.read_bytes())
  for it in a['compatibility_assets'].values(): inventory[it['path']]=file_sha(it['path'])
 return inventory
