 metadata={}
 try:
  tags=dep.local_metadata_transport('/api/tags')
  metadata['tags']={'reachable':True,'models':[{'name':m.get('name'),'digest':m.get('digest'),'matches_approved':m.get('name') in MODEL_DIGESTS and m.get('digest','').removeprefix('sha256:')==MODEL_DIGESTS[m['name']]} for m in tags.get('models',[]) if m.get('name') in MODEL_DIGESTS]}
  for model,spec in sources.items():
   info=dep.local_metadata_transport('/api/show',{'model':model}); template=info.get('template')
   metadata[model]={'reachable':True,'returned_model':info.get('details',{}).get('family') or info.get('model_info',{}).get('general.name'),'template_sha256':sha(template.encode()) if isinstance(template,str) else None,'template_matches_frozen':isinstance(template,str) and sha(template.encode())==spec['ollama_template_sha256']}
 except Exception as e: metadata['error']={'reachable':False,'error_type':type(e).__name__,'error':str(e)[:300]}
 probe=dep.probe_review_isolation()
 synthetic=eval_audit_isolation.run_preflight(command=[sys.executable,'/tmp/review_environment_audit_20261016.py','--stdout'])
 ps_after=ps(); after=snapshot_sources_and_providers()
 tags_ok=metadata.get('tags',{}).get('reachable') is True and {m['name']:m['matches_approved'] for m in metadata['tags']['models']}=={name:True for name in MODEL_DIGESTS}
 show_ok=all(metadata.get(m,{}).get('template_matches_frozen') is True for m in MODEL_DIGESTS)
 canary_ok=all(probe['checks'].values()) and synthetic['synthetic_preflight_passed'] is True
 frozen=before==after; resident_unchanged=ps_before==ps_after
 ok=tags_ok and show_ok and canary_ok and frozen and resident_unchanged and all(x['golden_cases']==9 and x['all_golden_full_ids_matched'] for x in models.values())
 script=Path(__file__).read_text()
 report={'schema_version':'local-review-environment-audit/v1','created_at':datetime.now(timezone.utc).isoformat(),'baseline_commit':'a0f1e1ab60e448f77357194360a4ebc12a8f98dc','platform':{'system':platform.system(),'release':platform.release(),'machine':platform.machine(),'host':platform.node(),'python':sys.version.split()[0],'executable':sys.executable,'prefix':sys.prefix},'command':{'executable':'workspace/review-environment/python311/bin/python','script':'/tmp/review_environment_audit_20261016.py','outer_timeout_seconds':600,'exit_code':0 if ok else 2},'source_manifest':str(SOURCES),'source_manifest_sha256':sha(SOURCES.read_bytes()),'source_and_provider_bytes_frozen':frozen,'source_inventory_sha256':before,'source_and_provider_inventory_sha256_after':after,'provider_source_files':[str(Path(dep.__file__).resolve()),str(Path(sys.modules['finetune.eval_review'].__file__).resolve()),str(Path(eval_audit_isolation.__file__).resolve())],'script_path':'/tmp/review_environment_audit_20261016.py','script_sha256':sha(script.encode()),'execution_script':script,'replay_command':'PYTHONPATH=<repository-root> <repository-root>/workspace/review-environment/python311/bin/python /tmp/review_environment_audit_20261016.py [--output /absolute/new/path.json | --stdout], under an outer subprocess timeout of 600 seconds. Default output is the canonical audit path and uses exclusive creation; reruns must choose a new --output path or --stdout.','replay_stdout_is_read_only':True,'approved_models':models,'local_metadata':metadata,'metadata_checks_passed':tags_ok and show_ok,'resident_models_before':ps_before,'resident_models_after':ps_after,'resident_model_inventory_unchanged':resident_unchanged,'sandbox_canary':{'checks':probe['checks'],'all_passed':all(probe['checks'].values()),'synthetic':True,'real_model_deployment_verified':False},'actor_sandbox_preflight':{'synthetic_preflight_passed':synthetic['synthetic_preflight_passed'],'actors':len(synthetic['actor_request_preflight']['actors']),'checks':probe['checks'],'admission_proof':False},'boundaries':{'model_generation_executed':False,'model_tensor_loading_executed':False,'real_test_used':False,'formal_evalclaim_created':False,'production_deployment_receipt_created':False,'network_external':False,'admission_proof':False,'ready_for_real_review':False},'duration_seconds':round(time.monotonic()-start,3)}
 return report
def write_new(path,data):
 path=Path(path).absolute(); fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'wb') as f: f.write(data); os.fchmod(f.fileno(),0o600)
def main():
 p=argparse.ArgumentParser(); p.add_argument('--output'); p.add_argument('--stdout',action='store_true'); a=p.parse_args()
 if a.stdout and a.output: p.error('--stdout and --output are mutually exclusive')
 r=run(); data=(json.dumps(r,ensure_ascii=False,indent=2)+'\n').encode()
 if a.stdout: sys.stdout.buffer.write(data)
 else: write_new(a.output or DEFAULT_OUT,data)
 return r['command']['exit_code']
if __name__=='__main__': raise SystemExit(main())
